const $ = id => document.getElementById(id);
const colors = ['#f9ce75','#eda28d','#9bbddc','#b1ca91','#c5afe0','#f3ede0'];
const names = ['ສີເຫຼືອງ','ສີບົວ','ສີຟ້າ','ສີຂຽວ','ສີມ່ວງ','ສີຄຣີມ'];
const roofs = ['#df826b','#779dbb','#83a17c','#b294bd','#d5b369','#8a9399'];
const categories = [ ['home','🏡','ແບບບ້ານ'],['wall','🎨','ສີບ້ານ'],['roof','🖌️','ສີຫຼັງຄາ'],['shape','🔺','ຊົງຫຼັງຄາ'],['door','🚪','ປະຕູ'],['windows','🪟','ປ່ອງຢ້ຽມ'],['garden','🌳','ສວນ'],['sky','🌤️','ທ້ອງຟ້າ'],['friend','🐱','ໝູ່ນ້ອຍ'] ];
const defaults = {wall:0,roof:0,door:0,windows:0,garden:0,home:0,shape:0,sky:0,friend:0};
const extraOptions = {home:[['🏡','ບ້ານນ້ອຍ'],['🏰','ປາສາດ'],['🍄','ບ້ານເຫັດ']],shape:[['🔺','ສາມຫຼ່ຽມ'],['◠','ໂຄ້ງມົນ'],['▱','ຊົງກວ້າງ']],sky:[['☀️','ກາງເວັນ'],['🌅','ຍາມແລງ'],['🌙','ກາງຄືນ']],friend:[['🐱','ແມວນ້ອຍ'],['🐶','ໝານ້ອຍ'],['🐰','ກະຕ່າຍ']]};
categories.push(['texture','🧱','ລາຍຝາ'],['path','🪨','ທາງຍ່າງ'],['decor','🎈','ຕົກແຕ່ງ'],['fence','🪵','ຮົ້ວ'],['lighting','💡','ໄຟສວນ'],['plants','🌼','ດອກໄມ້']);
Object.assign(defaults,{texture:0,path:0,decor:0,fence:0,lighting:0,plants:0});
Object.assign(extraOptions,{texture:[['🎨','ສີລຽບ'],['🧱','ອິດ'],['🪵','ໄມ້']],path:[['🏖️','ດິນຊາຍ'],['🪨','ກ້ອນຫີນ'],['🌸','ທາງດອກໄມ້']],decor:[['🎈','ປູມເປົ້າ'],['🚩','ທຸງສີ'],['💌','ຕູ້ຈົດໝາຍ']]});
Object.assign(extraOptions,{fence:[['🌿','ບໍ່ມີຮົ້ວ'],['🤍','ຮົ້ວຂາວ'],['🪵','ຮົ້ວໄມ້']],lighting:[['☀️','ບໍ່ມີໄຟ'],['💡','ໂຄມໄຟ'],['✨','ໄຟສີ']],plants:[['🌱','ຫຍ້າ'],['🌷','ດອກທິວລິບ'],['🌻','ດອກຕາເວັນ']]});
const countFor = key => ['wall','roof','garden'].includes(key)?6:3;
let state = {...defaults}, active = 'wall', history = [], sound = false, audio;
try { const saved = JSON.parse(localStorage.getItem('lyon-house-v1')); const merged={...defaults,...saved}; if(saved && categories.every(([key]) => Number.isInteger(merged[key]) && merged[key]>=0 && merged[key]<countFor(key))) state = merged; } catch {}
function persist(){try{localStorage.setItem('lyon-house-v1',JSON.stringify(state));}catch{}}
function tone(freq=520){if(!sound)return;try{audio ||= new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=freq;g.gain.setValueAtTime(.08,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.18);o.start();o.stop(audio.currentTime+.2);}catch{}}
function tree(x,y,size=1){return `<g transform="translate(${x} ${y}) scale(${size})"><rect x="-9" y="-45" width="18" height="90" rx="7" fill="#a27d56"/><circle cy="-66" r="47" fill="#78a36b"/><circle cx="-23" cy="-45" r="32" fill="#83ae74"/><circle cx="22" cy="-48" r="35" fill="#83ae74"/></g>`;}
function flower(x,y,c){return `<g transform="translate(${x} ${y})"><path d="M0 0v25m0-8q-15-15-18-3m18 8q15-15 18-4" fill="none" stroke="#618e52" stroke-width="4"/><g fill="${c}"><circle cx="-7" r="7"/><circle cx="7" r="7"/><circle cy="-7" r="7"/><circle cy="7" r="7"/></g><circle r="5" fill="#fff0a2"/></g>`;}
function render(){
 $('wall').setAttribute('fill',colors[state.wall]);$('roof').setAttribute('fill',roofs[state.roof]);$('roof').setAttribute('stroke',roofs[state.roof]);
 const dc=['#759c8a','#b98061','#a58aba'][state.door];
 $('door').innerHTML=`<path d="M365 486V403a35 35 0 0170 0v83Z" fill="${dc}" stroke="#fff3d8" stroke-width="7"/>${state.door===1?'<path d="M378 412h44v50h-44Z" fill="none" stroke="#f5dfbd" stroke-width="3"/>':state.door===2?'<circle cx="400" cy="408" r="16" fill="#dbf1ed"/>':''}<circle cx="420" cy="445" r="5" fill="#ffe5a3"/>`;
 $('windows').innerHTML=[295,505].map(x=>state.windows===1?`<circle cx="${x}" cy="365" r="27" fill="#cae6e9" stroke="#fff8e7" stroke-width="9"/><path d="M${x-24} 365h48m-24-24v48" stroke="#fff8e7" stroke-width="5"/>`:`<rect x="${x-27}" y="337" width="54" height="57" rx="${state.windows===2?22:4}" fill="#cbe8ed" stroke="#fff8e7" stroke-width="8"/><path d="M${x-25} 365h50m-25-25v51" stroke="#fff8e7" stroke-width="5"/>${state.windows===2?`<path d="M${x-34} 399h68" stroke="#b48267" stroke-width="10" stroke-linecap="round"/>`:''}`).join('');
 $('garden').innerHTML=state.garden===0?tree(140,445)+tree(656,430,.8):state.garden===1?tree(660,430,.8)+[110,150,190,590,630,675].map((x,i)=>flower(x,470+i%2*15,['#e99c92','#efc669','#c3a3ce'][i%3])).join(''):tree(135,440)+`<g stroke="#fff5df" stroke-width="13" stroke-linecap="round"><path d="M575 450h160m-160 30h160"/>${[580,615,650,685,720].map(x=>`<path d="M${x} 430v65"/>`).join('')}</g>`;
 renderExtras();syncWorld();$('undo').disabled=!history.length;persist();
}
function options(){
 $('tabs').innerHTML=categories.map(([id,icon,label])=>`<button class="tab" role="tab" aria-selected="${active===id}" data-tab="${id}"><span>${icon}</span>${label}</button>`).join('');
 $('choice-title').textContent=categories.find(c=>c[0]===active)[2]+'ທີ່ເຈົ້າມັກ';
 const isColor=active==='wall'||active==='roof';
 if(extraOptions[active]){ $('choices').innerHTML=extraOptions[active].map(([icon,label],i)=>`<button class="choice" aria-pressed="${state[active]===i}" data-choice="${i}"><span class="sample">${icon}</span>${label}</button>`).join('');return; }
 const labels=isColor?(active==='roof'?['ສີສົ້ມ','ສີຟ້າ','ສີຂຽວ','ສີມ່ວງ','ສີທອງ','ສີເທົາ']:names):active==='door'?['ທຳມະດາ','ລາຍໄມ້','ມີປ່ອງ']:active==='windows'?['ສີ່ຫຼ່ຽມ','ວົງມົນ','ໂຄ້ງມົນ']:['ຕົ້ນໄມ້','ດອກໄມ້','ຮົ້ວນ້ອຍ','ສະນ້ຳ','ສວນຜັກ','ຊິງຊ້າ'];
 $('choices').innerHTML=labels.map((name,i)=>`<button class="choice" aria-pressed="${state[active]===i}" data-choice="${i}">${isColor?`<span class="swatch" style="background:${(active==='wall'?colors:roofs)[i]}"></span>`:`<span class="sample">${(active==='door'?['🚪','▥','◉']:active==='windows'?['⊞','⊕','▰']:['🌳','🌷','🏡','🐟','🥕','🛝'])[i]}</span>`}${name}</button>`).join('');
}
 $('tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b){active=b.dataset.tab;options();$('tabs').querySelector(`[data-tab="${active}"]`).focus();tone(440);}});
 $('tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const i=categories.findIndex(c=>c[0]===active),n=categories.length;active=categories[e.key==='Home'?0:e.key==='End'?n-1:(i+(e.key==='ArrowRight'?1:n-1))%n][0];options();$('tabs').querySelector(`[data-tab="${active}"]`).focus();});
 $('choices').addEventListener('click',e=>{const b=e.target.closest('[data-choice]');if(!b)return;const value=Number(b.dataset.choice);if(state[active]!==value){history.push({...state});state[active]=value;render();options();$('choices').children[value].focus();tone();$('status').textContent='ປ່ຽນແລ້ວ!';}});
 $('undo').onclick=()=>{if(history.length){state=history.pop();render();options();tone(350);}};
 $('reset').onclick=()=>{history.push({...state});state={...defaults};render();options();tone(350);};
 $('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'🔊':'🔇';$('sound').setAttribute('aria-pressed',sound);$('sound').setAttribute('aria-label',sound?'ປິດສຽງ':'ເປີດສຽງ');tone();};
 $('finish').onclick=()=>{$('celebrate').showModal();tone(660);$('confetti').innerHTML=Array.from({length:35},(_,i)=>`<i class="paper" style="left:${Math.random()*100}%;background:${colors[i%6]};animation-delay:${Math.random()*.6}s"></i>`).join('');setTimeout(()=>$('confetti').replaceChildren(),3300);};
 $('continue').onclick=()=>$('celebrate').close();
 $('save').onclick=()=>{const svg=$('scene').cloneNode(true);svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.setAttribute('width','1200');svg.setAttribute('height','930');const blob=new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='my-lyon-house.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function renderExtras(){
 $('house-side').setAttribute('fill',colors[state.wall]);$('house-side').setAttribute('opacity','.72');$('roof-side').setAttribute('fill',roofs[state.roof]);$('roof-side').setAttribute('stroke',roofs[state.roof]);
 $('wall-detail').innerHTML=state.texture===0?'':state.texture===1?Array.from({length:7},(_,i)=>`<path d="M249 ${313+i*25}h302m-${i%2?270:245} 0v25m60-25v25m60-25v25m60-25v25" fill="none" stroke="#fff8e5" stroke-opacity=".4" stroke-width="3"/>`).join(''):Array.from({length:9},(_,i)=>`<path d="M${260+i*34} 310v174" stroke="#936943" stroke-opacity=".23" stroke-width="3"/>`).join('');
 $('path-detail').innerHTML=state.path===1?Array.from({length:5},(_,i)=>`<ellipse cx="${400+(i%2?14:-14)}" cy="${510+i*24}" rx="${22+i*5}" ry="9" fill="${i%2?'#b9bdba':'#deded2'}" stroke="#a6aaa0" stroke-width="2"/>`).join(''):state.path===2?Array.from({length:5},(_,i)=>flower(360-i*13,510+i*24,'#e9a7bd')+flower(452+i*13,510+i*24,'#e6c45e')).join(''):'';
 $('decorations').innerHTML=state.decor===0?['#ee9e9d','#eec963','#a8cde0'].map((c,i)=>`<path d="M${105+i*31} ${280+i%2*22}Q160 340 150 410" fill="none" stroke="#8b9986" stroke-width="2"/><ellipse cx="${105+i*31}" cy="${260+i%2*22}" rx="20" ry="26" fill="${c}"/>`).join(''):state.decor===1?'<path d="M240 314Q400 355 560 314" stroke="#8e7963" fill="none" stroke-width="3"/>'+Array.from({length:8},(_,i)=>`<path d="M${250+i*37} ${320+Math.sin(i/7*Math.PI)*19}l26 2-13 23Z" fill="${colors[i%6]}"/>`).join(''):'<path d="M610 470v70" stroke="#a98059" stroke-width="9"/><rect x="583" y="437" width="58" height="42" rx="12" fill="#dc9986"/><path d="M595 452h32m7-5v-27h18v13h-18" fill="#efc467" stroke="#8b6956" stroke-width="3"/>';
 const shape=['M218 292L400 149 582 292Z','M218 292Q400 60 582 292Z','M218 292L285 190H515L582 292Z'][state.shape];
 $('roof').setAttribute('d',shape);$('roof-pattern').setAttribute('d',shape);
 $('home-extra').innerHTML=state.home===1?[230,570].map(x=>`<g><rect x="${x-30}" y="275" width="60" height="215" rx="6" fill="${colors[state.wall]}" stroke="#fff0da" stroke-width="5"/><path d="M${x-39} 282L${x} 214L${x+39} 282Z" fill="${roofs[state.roof]}"/><rect x="${x-10}" y="320" width="20" height="35" rx="10" fill="#cbe8ed"/><path d="M${x} 213v-48l30 12-30 12" fill="#ecc55d" stroke="#ad8c68" stroke-width="3"/></g>`).join(''):state.home===2?`<path d="M210 292Q215 122 400 130Q585 122 590 292Z" fill="${roofs[state.roof]}" stroke="#fff0da" stroke-width="6"/>${[[310,220,23],[400,180,26],[490,230,23],[400,263,18]].map(([x,y,r])=>`<circle cx="${x}" cy="${y}" r="${r}" fill="#fff0da"/>`).join('')}`:'';
 $('sky-bg').setAttribute('fill',['#ddf2ef','#f5d6cd','#303b68'][state.sky]);
 $('sun').setAttribute('fill',state.sky===2?'#fff3bf':'#ffcd62');
 $('sky-extra').innerHTML=state.sky===2?Array.from({length:20},(_,i)=>`<circle cx="${35+(i*107)%730}" cy="${35+(i*43)%240}" r="${i%3+1}" fill="#fff6ce"/>`).join(''):state.sky===1?'<path d="M65 285Q120 165 190 285" fill="none" stroke="#e4a79a" stroke-width="15"/><path d="M80 285Q125 195 175 285" fill="none" stroke="#f3cf79" stroke-width="12"/>':'';
 if(state.garden===3)$('garden').innerHTML=tree(140,430,.8)+'<ellipse cx="655" cy="478" rx="87" ry="35" fill="#e0d7b8"/><ellipse cx="655" cy="474" rx="75" ry="27" fill="#8fcbd1"/><path d="M620 472q15-15 30 0-15 15-30 0l-10-8v16Z" fill="#f4b35d"/><ellipse cx="685" cy="465" rx="16" ry="8" fill="#83af76"/>';
 if(state.garden===4)$('garden').innerHTML=tree(665,425,.8)+[0,1,2].map(i=>`<rect x="65" y="${430+i*27}" width="145" height="22" rx="10" fill="#b8916e"/>${[90,130,170].map(x=>`<path d="M${x} ${439+i*27}l-7-19m7 19 8-19m-8 19v-24" stroke="#76a35e" stroke-width="6" stroke-linecap="round"/>`).join('')}`).join('');
 if(state.garden===5)$('garden').innerHTML=tree(140,430,.8)+'<path d="M590 495l25-150h75l35 150M600 355h105" fill="none" stroke="#b68b65" stroke-width="10" stroke-linecap="round"/><path d="M635 355v105m40-105v105" stroke="#f9edc4" stroke-width="4"/><rect x="622" y="455" width="66" height="12" rx="5" fill="#df947e"/>';
 const petColor=['#dfa26b','#b68d70','#f5ece3'][state.friend];
 $('pet').innerHTML=`<g transform="translate(535 535)"><ellipse cy="17" rx="28" ry="7" fill="#547850" opacity=".15"/><ellipse cy="1" rx="19" ry="18" fill="${petColor}"/>${state.friend===2?'<ellipse cx="-9" cy="-36" rx="7" ry="21" fill="#f5ece3"/><ellipse cx="9" cy="-36" rx="7" ry="21" fill="#f5ece3"/>':state.friend===0?`<path d="M-18-13l-2-24 18 14 18-14 2 24" fill="${petColor}"/>`:'<ellipse cx="-20" cy="-17" rx="9" ry="19" fill="#795a47"/><ellipse cx="20" cy="-17" rx="9" ry="19" fill="#795a47"/>'}<circle cy="-15" r="20" fill="${petColor}"/><circle cx="-7" cy="-18" r="2.5" fill="#45423b"/><circle cx="7" cy="-18" r="2.5" fill="#45423b"/><path d="M-3-10h6l-3 4Z" fill="#a76468"/></g>`;
}
 $('surprise').onclick=()=>{history.push({...state});for(const [key] of categories)state[key]=Math.floor(Math.random()*countFor(key));render();options();tone(740);$('status').textContent='ບ້ານແບບໃໝ່!';};
function syncWorld(){const frame=document.querySelector('.world-frame');if(frame?.contentWindow)frame.contentWindow.postMessage({type:'lyon-design',wall:colors[state.wall],roof:roofs[state.roof],sky:state.sky,design:{...state}},location.origin);}
document.querySelector('.world-frame')?.addEventListener('load',syncWorld);
 active='home';render();options();
